            "type": "splunk.markdown"
        },
        "viz_CZF9chHU": {
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/Splunk-DNS-Guard-AI/images/logo-nobg.png"
            },
            "type": "splunk.image"
        },
        "viz_CcUQr1i8": {
            "eventHandlers": [],
            "options": {
                "fillColor": "#000000",
                "fillOpacity": 0.89,
                "rx": 10,
                "strokeColor": "transparent"
            },
            "type": "splunk.rectangle"
        },
