        "viz_nhZLKqJV": {
            "eventHandlers": [],
            "options": {
                "fillColor": "#000000",
                "fillOpacity": 0.89,
                "rx": 10,
                "strokeColor": "transparent"
            },
            "type": "splunk.rectangle"
        },
        "viz_sa8rWrPI": {
            "context": {
                "DisabledColumnFormatEditorConfig": {
                    "string": {
                        "unitPosition": "after"
                    }
                },
                "DisabledRowBackgroundColorsEditorConfig": [
                    {
                        "match": "True",
                        "value": "#FE3A3A"
                    },
                    {
                        "match": "False",
                        "value": "#2eb82e"
                    }
                ],
                "DisabledRowColorsEditorConfig": [
                    "#ffffff"
                ]
            },
            "dataSources": {
                "primary": "ds_mReZg6Gn"
            },
            "options": {
                "backgroundColor": "transparent",
                "columnFormat": {
                    "Condition": {
                        "width": 60
                    },
                    "Description": {
                        "width": 90
                    },
                    "Disabled": {
                        "align": "auto",
                        "data": "> table | seriesByName(\"Disabled\") | formatByType(DisabledColumnFormatEditorConfig)",
                        "headerAlign": "auto",
                        "rowBackgroundColors": "> table | seriesByName(\"Disabled\") | matchValue(DisabledRowBackgroundColorsEditorConfig)",
                        "rowColors": "> table | seriesByName('Disabled') | pick(DisabledRowColorsEditorConfig)",
                        "textOverflow": "break-word"
                    },
                    "Risk Value": {
                        "width": 60
                    },
                    "Value Type": {
                        "width": 60
                    }
                },
                "tableFormat": {
                    "align": "center",
                    "headerAlign": "center",
                    "headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
                    "headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
                    "rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
                }
            },
            "type": "splunk.table"
        },
        "viz_u1zubxrH": {
            "eventHandlers": [],
            "options": {
                "fillColor": "#000000",
                "fillOpacity": 0.89,
                "rx": 10,
                "strokeColor": "transparent"
            },
            "type": "splunk.rectangle"
        }
    },
    "dataSources": {
        "ds_mReZg6Gn": {
            "name": "Search_1",
            "options": {
                "query": "| rest/servicesNS/-/Splunk-DNS-Guard-AI/configs/conf-risk_factors splunk_server=local\n| search title=\"DNS Guard AI*\"\n| spath input=conditions\n| rename {}.comparator as comparator {}.field as field {}.value as val {}.value_type as value_type\n| eval disabled = if(disabled=\"1\", \"True\", \"False\"), comparator = case(comparator=\"equal\", \" = \"), condition = field . comparator . value\n| table title description condition value disabled\n| rename title as Factor description as Description condition as Condition value as \"Risk Value\" disabled as Disabled",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        }
    },
    "layout": {
        "globalInputs": [],
